const pyCode = `
import openpyxl, os, json, sys
from openpyxl.worksheet.datavalidation import DataValidation

excel_path = sys.argv[1]
img_dir    = sys.argv[2]

wb = openpyxl.load_workbook(excel_path)
ws = wb['Script Editor']

TEXT_COL   = 1
IMAGE_COL  = 2
DATA_START = 4

data_rows = []
for row in ws.iter_rows(min_row=DATA_START):
    val = ws.cell(row=row[0].row, column=TEXT_COL).value
    if val and str(val).strip():
        data_rows.append(row[0].row)

n = len(data_rows)
print(f"Script rows found: {n}", file=sys.stderr)

if n < 2:
    print(json.dumps({"success": False, "reason": "too few rows", "paragraphs": n}))
    sys.exit(0)

for i, row_num in enumerate(data_rows):
    ws.cell(row=row_num, column=IMAGE_COL).value = i

gen_images = sorted(
    [f.replace('.jpeg','') for f in os.listdir(img_dir)
     if f.startswith('image') and f.endswith('.jpeg') and f != 'image0.jpeg'],
    key=lambda x: int(x.replace('image','')) if x.replace('image','').isdigit() else 9999
)

if 'Image Reference' in wb.sheetnames:
    ref_ws = wb['Image Reference']
    for row in ref_ws.iter_rows(min_row=2):
        for cell in row:
            cell.value = None
    for idx, name in enumerate(gen_images):
        ref_ws.cell(row=idx+2, column=1).value = int(name.replace('image',''))
        ref_ws.cell(row=idx+2, column=2).value = name + '.jpeg'

ws.data_validations.dataValidation = [
    dv for dv in ws.data_validations.dataValidation
    if 'B' not in str(dv.sqref)
]

max_img  = max([int(name.replace('image','')) for name in gen_images], default=0)
num_list = ','.join(str(x) for x in range(0, max_img + 1))
dv = DataValidation(
    type='list',
    formula1='"' + num_list + '"',
    allow_blank=True,
    showErrorMessage=False
)
last_row = data_rows[-1]
dv.sqref = f'B{DATA_START}:B{last_row}'
ws.add_data_validation(dv)

wb.save(excel_path)
print(json.dumps({
    "success":         True,
    "paragraphs":      n,
    "images_assigned": n,
    "first_row":       0,
    "last_row":        0,
    "middle":          f"1 to {n-2}" if n > 2 else "none"
}))
`;

