excel_path = sys.argv[1]
img_dir    = sys.argv[2]
wb = openpyxl.load_workbook(excel_path)
ws = wb['Script Editor']
TEXT_COL   = 1
IMAGE_COL  = 2
DATA_START = 4
data_rows = []
for row in ws.iter_rows(min_row=DATA_START):
    val = ws.cell(row=row[0].row, column=TEXT_COL).value
    if val and str(val).strip():
        data_rows.append(row[0].row)
n = len(data_rows)
for i, row_num in enumerate(data_rows):
    ws.cell(row=row_num, column=IMAGE_COL).value = i
gen_images = sorted(
    [f.replace('.jpeg','') for f in os.listdir(img_dir)
     if f.startswith('image') and f.endswith('.jpeg') and f != 'image0.jpeg'],
    key=lambda x: int(x.replace('image','')) if x.replace('image','').isdigit() else 9999
)
if 'Image Reference' in wb.sheetnames:
    ref_ws = wb['Image Reference']
    for row in ref_ws.iter_rows(min_row=2):
        for cell in row: cell.value = None
    for idx, name in enumerate(gen_images):
        ref_ws.cell(row=idx+2, column=1).value = int(name.replace('image',''))
        ref_ws.cell(row=idx+2, column=2).value = name + '.jpeg'
ws.data_validations.dataValidation = [
    dv for dv in ws.data_validations.dataValidation if 'B' not in str(dv.sqref)
]
